"""Catalogue label aliases from the website's src/config/catalog-labels.ts.

Usage: python3 tool/gen_labels.py <site-root>
"""
import re, sys
from pathlib import Path

source = (Path(sys.argv[1]) / "src/config/catalog-labels.ts").read_text()
block = source[source.index("LABEL_ENTRIES"):source.index("const LABEL_ALIASES")]
pairs = re.findall(r'\[\s*"([^"]+)",\s*"([^"]+)"\s*\]', block)
lines = "\n".join(f"  '{k}': '{v}'," for k, v in dict(pairs).items())
out = Path(__file__).resolve().parent.parent / "lib/catalog/labels.g.dart"
out.write_text(
    "// Generated by tool/gen_labels.py from the website's catalog-labels.ts.\n\n"
    "/// Catalogue field id → the website's message path (`catalogLabelPath`).\n"
    f"const catalogLabelPaths = <String, String>{{\n{lines}\n}};\n"
)
print(len(pairs), "labels")
